	for _, argument := range call.Args {
		if c.expressionUsesObject(argument, object) {
			if variable, ok := object.(*types.Var); ok &&
				(isBoolean(variable.Type()) || isInteger(variable.Type())) &&
				!c.scalarEscapesInExpression(argument, object) {
				continue
			}
			return true
		}
	}
	return false
